PREFIX sosa:    <http://www.w3.org/ns/sosa/>
PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX qudt:    <http://qudt.org/schema/qudt/>
PREFIX xsd:     <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?meanMonthlyFlow
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    {
      SELECT ?month (AVG(xsd:decimal(?val)) AS ?meanMonthlyFlow)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty envthes:30106;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .

        ?res qudt:numericValue ?val .

        BIND(YEAR(?t) AS ?year)
        FILTER(?year = 2002)

        BIND(MONTH(?t) AS ?month)
      }
      GROUP BY ?month
      ORDER BY DESC(?meanMonthlyFlow)
      LIMIT 1
    }
  }
}

generated_sparql:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX hydrorwth: <https://hydro-knowledge-graph-f48785.pages.rwth-aachen.de/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year (AVG(xsd:decimal(?value)) AS ?averageAnnualPrecipitation)
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    ?observation rdf:type sosa:Observation ;
      sosa:observedProperty hydrorwth:hasMeanDailyPrecip ;
      sosa:resultTime ?time ;
      sosa:hasResult ?result .
    ?result qudt:quantityValue ?quantityValue .
    ?quantityValue qudt:numericValue ?value .
    BIND(YEAR(xsd:dateTime(?time)) AS ?year)
  }
}
GROUP BY ?year
HAVING (AVG(xsd:decimal(?value)) < 1200)
ORDER BY ?year

actual_sparql:
PREFIX sosa:    <http://www.w3.org/ns/sosa/>
PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX qudt:    <http://qudt.org/schema/qudt/>
PREFIX xsd:     <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?avgAnnualPrecip
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    {
      # for a given year, take the average over all catchments 
      SELECT ?year (AVG(?annualTotal) AS ?avgAnnualPrecip)
      WHERE {
        {
         # take annual total per catchment
          SELECT ?year ?catchment (SUM(xsd:decimal(?val)) AS ?annualTotal)
          WHERE {
            ?obs a sosa:Observation ;
                sosa:observedProperty envthes:30106 ;
                sosa:hasFeatureOfInterest ?catchment ;
                sosa:resultTime ?t ;
                sosa:hasResult ?res .

            ?res qudt:numericValue ?val .
            BIND(YEAR(?t) AS ?year)
          }
          GROUP BY ?year ?catchment
        }
      }
      GROUP BY ?year
    }

    FILTER(?avgAnnualPrecip < 1200)
  }
}
ORDER BY ?year

